class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __eq__(self, other):
        if not isinstance(other, Point):
            return NotImplemented                     # let the other type try
        return (self.x, self.y) == (other.x, other.y)

print("object.__hash__ ->", object.__hash__ is not None)
print("Point.__hash__  ->", Point.__hash__)
print("Point(1, 2) == Point(1, 2) ->", Point(1, 2) == Point(1, 2))
try:
    seen = {Point(1, 2)}
except TypeError as exc:
    print("TypeError:", exc)

class Tag:
    def __init__(self, name):
        self.name = name

    def __eq__(self, other):
        return isinstance(other, Tag) and self.name == other.name

    def __hash__(self):
        return hash(self.name)          # derived from a MUTABLE attribute

    def __repr__(self):
        return f"Tag({self.name!r})"

seen = {Tag("prod")}
t = next(iter(seen))
print("before  t in seen  =", t in seen)

t.name = "staging"                      # the hash of a live set member just changed

print("len(seen)          =", len(seen))
print("list(seen)         =", list(seen))
print("t in seen          =", t in seen)
print("Tag('staging') in  =", Tag("staging") in seen)
print("identity search    =", any(x is t for x in seen))

from functools import total_ordering

class Money:
    def __init__(self, minor, currency="USD"):
        self.minor, self.currency = minor, currency

    def __repr__(self):
        return f"Money({self.minor}, {self.currency!r})"

try:
    sorted([Money(500), Money(100)])
except TypeError as exc:
    print("TypeError:", exc)

@total_ordering
class Ordered(Money):
    def __eq__(self, other):
        if not isinstance(other, Ordered):
            return NotImplemented
        return (self.currency, self.minor) == (other.currency, other.minor)

    def __lt__(self, other):
        if not isinstance(other, Ordered):
            return NotImplemented
        if self.currency != other.currency:
            raise TypeError(f"cannot order {self.currency} against {other.currency}")
        return self.minor < other.minor

    __hash__ = None       # explicit: this type is mutable, keep it out of dicts

print("sorted     ->", sorted([Ordered(500), Ordered(100), Ordered(250)]))
print("a >= b     ->", Ordered(500) >= Ordered(100))
print("max        ->", max(Ordered(500), Ordered(100)))
try:
    Ordered(100, "USD") < Ordered(100, "EUR")
except TypeError as exc:
    print("TypeError:", exc)

class Countdown:
    """A self-iterator: __iter__ returns self, so it can be consumed exactly once."""

    def __init__(self, n):
        self.n = n

    def __iter__(self):
        return self

    def __next__(self):
        if self.n <= 0:
            raise StopIteration
        self.n -= 1
        return self.n + 1

c = Countdown(3)
print("first pass  =", list(c))
print("second pass =", list(c))          # exhausted, and nothing tells you

class Countdown2:
    """__iter__ hands back a fresh iterator every time; __len__ drives truthiness."""

    def __init__(self, n):
        self.n = n

    def __iter__(self):
        return iter(range(self.n, 0, -1))

    def __len__(self):
        return self.n

c2 = Countdown2(3)
print("first pass  =", list(c2))
print("second pass =", list(c2))
print("len         =", len(c2), "| bool =", bool(c2))
empty = Countdown2(0)
print("empty len   =", len(empty), "| bool =", bool(empty))
print("branch      =", "has items" if empty else "falsy because __len__ is 0")

