class Session:
    active = {}                      # ONE dict, created once, owned by the class

    def __init__(self, user):
        self.user = user
        self.active[user] = self      # every instance writes into the same dict

    def __repr__(self):
        return f"Session({self.user!r})"

def handle_request(user):
    return Session(user)

handle_request("ana")
handle_request("ben")
print("Session.active     =", Session.active)
print("a fresh instance   =", Session("cleo").active)      # sees the other two
print("leaks per process  =", len(Session.active))

