from dataclasses import dataclass

@dataclass(frozen=True, order=True)
class Money:
    currency: str            # ordered by currency first, then amount
    minor: int               # integer minor units: no float equality anywhere

    @classmethod
    def parse(cls, text):
        amount, currency = text.split()
        return cls(currency, round(float(amount) * 100))

    def __str__(self):
        return f"{self.minor / 100:,.2f} {self.currency}"

prices = [Money.parse("12.50 USD"), Money.parse("9.99 USD"), Money.parse("9.99 EUR")]
print("repr      ->", repr(prices[0]))
print("str       ->", str(prices[0]))
print("sorted    ->", [str(p) for p in sorted(prices)])
print("dedupe    ->", len({*prices, Money.parse("12.50 USD")}))
print("dict key  ->", {prices[0]: "line-1"}[Money("USD", 1250)])
print("eq/hash   ->", Money("USD", 1250) == prices[0], hash(Money("USD", 1250)) == hash(prices[0]))
